let version=0,files=['A','B'],amberBase=0,blueDone=false,amberDone=false;const show=(m='Predict the next commit.')=>{world.textContent=`Current version: ${version}
Current files: ${files.join(', ')}
Amber base: ${amberBase}
Pinned reader at v0: A, B
${m}`};blue.onclick=()=>{if(blueDone)return show('Blue already committed.');if(version!==0)return show('Blue base is stale; reset to explore Blue first.');files.push('C');version++;blueDone=true;show('Blue committed atomically.')};amber.onclick=()=>{if(amberDone)return show('Amber already committed.');if(amberBase!==version)return show('CONFLICT: no files published. Refresh and validate append.');files.push('D');version++;amberDone=true;show('Amber committed atomically.')};refresh.onclick=()=>{amberBase=version;show('Independent append validated; Amber can retry.')};reset.onclick=()=>{version=0;files=['A','B'];amberBase=0;blueDone=false;amberDone=false;show()};show();
function paintConcept(){

vscene.innerHTML='<div style="display:grid;gap:14px"><div style="border:2px dashed #aac4c9;padding:12px">Pinned reader → <b>v0: [A] [B]</b><br>Its file list does not change.</div><div style="border:3px solid #9fd9b6;padding:12px">Published pointer → <b>v'+version+'</b><div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:8px">'+files.map(f=>'<span style="padding:10px;border:1px solid">File '+f+'</span>').join('')+'</div></div><div style="border-left:5px solid '+(amberBase===version?'#9fd9b6':'#ffbba5')+';padding:12px">Amber prepared from <b>v'+amberBase+'</b> → compare with published <b>v'+version+'</b><br>'+(amberDone?'D is already in the published list.':amberBase===version?'MATCH: appending D may publish the next list.':'MISMATCH: stop here. Refresh the base before retrying.')+'</div></div>';

}
["blue", "amber", "refresh", "reset"].forEach(id=>{const el=document.getElementById(id);["onclick","oninput","onchange"].forEach(kind=>{const prior=el[kind];if(prior)el[kind]=function(...args){const result=prior.apply(this,args);paintConcept();return result;};});});paintConcept();

const show=()=>{const l=+layers.value,a=+attempts.value,n=single.checked?a:a**l;world.textContent=`Layers: ${l}; total attempts: ${a}
Worst-case leaf calls / original request: ${n}
For 100 original requests: ${100*n}
Extra leaf calls per request: ${n-1}`};[layers,attempts,single].forEach(e=>e.oninput=show);show();
function paintConcept(){

const vL=+layers.value,vA=+attempts.value;let vCount=1;
vscene.innerHTML='<p>One original request enters at the top. Each row is one call boundary.</p><ol style="padding-left:28px"><li><b>1 original request</b></li>'+Array.from({length:vL},(_,i)=>{let before=vCount;const multiplier=single.checked&&i>0?1:vA;vCount*=multiplier;return '<li style="padding:10px 0;border-bottom:1px solid #6e9199">Layer '+(i+1)+': '+before+' incoming × <b>'+multiplier+' attempt'+(multiplier===1?'':'s')+'</b> = <strong>'+vCount+' outgoing</strong><div style="display:flex;gap:3px;flex-wrap:wrap;margin-top:6px">'+Array.from({length:Math.min(vCount,30)},()=>'<span aria-hidden="true" style="width:9px;height:16px;background:#a7ddc5"></span>').join('')+(vCount>30?'<span>… '+vCount+' total</span>':'')+'</div></li>'}).join('')+'</ol><p><b>Leaf work: '+vCount+' calls</b>. Blocks count individual attempts up to 30; the number remains exact. Worst-case failures at every retrying boundary; timing and jitter are outside this model.</p>';

}
["layers", "attempts", "single"].forEach(id=>{const el=document.getElementById(id);["onclick","oninput","onchange"].forEach(kind=>{const prior=el[kind];if(prior)el[kind]=function(...args){const result=prior.apply(this,args);paintConcept();return result;};});});paintConcept();

const show=()=>{const s=+slo.value,b=+bad.value;if(s<90||s>99.99)return world.textContent='Enter an SLO from 90 to 99.99.';const budget=10000*(1-s/100);world.textContent=`Bad deliveries: ${b}
Budget: ${budget.toFixed(1)} deliveries
Consumed: ${(b/budget*100).toFixed(1)}%
Remaining: ${(budget-b).toFixed(1)}
${b>budget?'Budget exceeded: apply the agreed policy.':'Assess trend and impact before the decision.'}`};[slo,bad].forEach(e=>e.oninput=show);show();
function paintConcept(){

const vs=+slo.value,vb=+bad.value,vBudget=10000*(1-vs/100);
if(vs<90||vs>99.99){vscene.innerHTML='<p>Enter a valid SLO to place the budget boundary.</p>';return;}
const vScale=Math.max(150,vBudget);
vscene.innerHTML='<p>Same denominator: <b>10,000 deliveries</b>. Ruler: 0–'+vScale.toFixed(0)+' bad deliveries.</p><div style="position:relative;height:92px;margin:30px 8px 10px;border-bottom:2px solid #9bb8bf"><div style="position:absolute;bottom:0;height:38px;width:'+vb/vScale*100+'%;background:#ffbba5;border:1px solid #fff"></div><div style="position:absolute;left:'+vBudget/vScale*100+'%;bottom:0;height:78px;border-left:3px dashed #bce4a9"></div><span style="position:absolute;top:0;right:0">Budget mark: '+vBudget.toFixed(1)+'</span></div><p>Actual bar: <b>'+vb+'</b> bad deliveries → '+(vb>vBudget?'<b>over by '+(vb-vBudget).toFixed(1)+'</b>':'<b>'+ (vBudget-vb).toFixed(1)+' left</b>')+'. The policy decision uses this gap and customer impact.</p>';

}
["slo", "bad"].forEach(id=>{const el=document.getElementById(id);["onclick","oninput","onchange"].forEach(kind=>{const prior=el[kind];if(prior)el[kind]=function(...args){const result=prior.apply(this,args);paintConcept();return result;};});});paintConcept();

let durable={status:'planned',evidence:[]},working='fresh';const show=()=>world.textContent=`Working memory: ${working}
Durable status: ${durable.status}
Evidence: ${durable.evidence.join(', ')||'none'}
Next: ${durable.status==='planned'?'write artifact':durable.status==='written'?'run checks':'continue to next bounded unit'}`;write.onclick=()=>{if(durable.status==='planned'){durable.status='written';working='artifact produced'}else working='existing artifact reused';show()};verify.onclick=()=>{if(durable.status==='planned'){working='blocked: no artifact'}else{durable.status='verified';durable.evidence=['simulated check passed'];working='verification recorded'}show()};restart.onclick=()=>{working='fresh session; read durable record';show()};reset.onclick=()=>{durable={status:'planned',evidence:[]};working='fresh';show()};show();
function paintConcept(){

const vStages=['planned','written','verified'],vAt=vStages.indexOf(durable.status);
vscene.innerHTML='<div style="border:2px dashed #ffbba5;padding:12px"><b>Temporary session</b><p>'+working+'</p><small>A new session replaces this memory.</small></div><p style="text-align:center">↓ read / write durable handoff ↓</p><div style="border:3px double #b3dec4;padding:12px"><b>Persistent record</b><ol>'+vStages.map((s,i)=>'<li style="padding:7px;'+(i===vAt?'border:2px solid #b3dec4':'')+'">'+(i<vAt?'✓ completed: ':i===vAt?'→ current: ':'pending: ')+s+'</li>').join('')+'</ol><b>Evidence stored:</b> '+(durable.evidence.join(', ')||'none — writing alone is not verification')+'</div>';

}
["write", "verify", "restart", "reset"].forEach(id=>{const el=document.getElementById(id);["onclick","oninput","onchange"].forEach(kind=>{const prior=el[kind];if(prior)el[kind]=function(...args){const result=prior.apply(this,args);paintConcept();return result;};});});paintConcept();

let state={},chain=[];const show=(m='Build a valid chain before writing the request.')=>world.textContent=`State: ${JSON.stringify(state,null,2)}
Chain: ${chain.join(' → ')||'empty'}
${m}`;list.onclick=()=>{state={datasetId:'demo-orders'};chain=['listDatasets'];show()};fresh.onclick=()=>{if(!state.datasetId)return show('Invalid dependency: datasetId is missing.');state.delayMinutes=18;chain=['listDatasets','fetchFreshness'];delete state.explanation;show()};explain.onclick=()=>{if(state.delayMinutes===undefined)return show('Invalid dependency: measurement is missing.');state.explanation='Demo upstream arrival is 18 minutes late.';chain=['listDatasets','fetchFreshness','explainDelay'];show('Matching request: Inspect freshness for the demo dataset and explain the observed delay.')};reset.onclick=()=>{state={};chain=[];show()};show();
function paintConcept(){

vscene.innerHTML='<ol style="padding-left:28px"><li style="padding:12px;border-bottom:1px solid #8ca9b0"><b>listDatasets()</b><br>Output wire: '+(state.datasetId?'<strong>datasetId = demo-orders</strong>':'empty — run this first')+'</li><li style="padding:12px;border-bottom:1px solid #8ca9b0">↓ requires datasetId<br><b>fetchFreshness(id)</b><br>'+(state.datasetId?'Input connected.':'STOP: input wire empty.')+'<br>Output wire: '+(state.delayMinutes===undefined?'empty':'<strong>delayMinutes = 18</strong>')+'</li><li style="padding:12px">↓ requires measurement<br><b>explainDelay(measurement)</b><br>'+(state.delayMinutes===undefined?'STOP: measurement missing.':state.explanation||'Ready to explain the 18-minute delay.')+'</li></ol><p>A matching training request can be written only after a valid executable path is established. No repair/write tool exists in this toy chain.</p>';

}
["list", "fresh", "explain", "reset"].forEach(id=>{const el=document.getElementById(id);["onclick","oninput","onchange"].forEach(kind=>{const prior=el[kind];if(prior)el[kind]=function(...args){const result=prior.apply(this,args);paintConcept();return result;};});});paintConcept();
